import { Box, Button, Typography } from '@mui/material'
import { useEffect, useMemo, useState, type KeyboardEvent } from 'react'
import { cardCommitLabel, type CardCommit } from '../../services/actions/card_commit_history'
import { DiffViewModeControl } from '../actions/conversation/events/diff_view_mode_control'
import type { CardMarkdownDataSource } from '../editor/data_sources/card_markdown_data_source'
import type { MarkdownBindingKind } from '../editor/data_sources/markdown_data_source'
import { useActiveCard } from '../hooks/use_active_card'
import { CommitDiffWorkspaceSource } from './diff_workspace/commit_diff_workspace_source'
import { DiffWorkspace } from './diff_workspace/diff_workspace'
import { DiffWorkspaceSearchButton } from './diff_workspace/diff_workspace_search_button'
import { DiffWorkspaceSearchService } from './diff_workspace/diff_workspace_search_service'
import { DiffWorkspaceService } from './diff_workspace/diff_workspace_service'
import type { DiffWorkspaceSource } from './diff_workspace/diff_workspace_types'
import { WorktreeDiffWorkspaceSource } from './diff_workspace/worktree_diff_workspace_source'

export type CardDiffSelection =
    | { commit: CardCommit, kind: 'commit' }
    | { kind: 'worktree' }

interface CardCommitDiffPanelProps {
    binding: Exclude<MarkdownBindingKind, 'list-action'>
    dataSource?: CardMarkdownDataSource
    onExit: () => void
    selection: CardDiffSelection
}

const UNAVAILABLE_COMMIT_MESSAGE = 'Commit is no longer available in this repository'

function createWorkspaceSource(cardPath: string | null, commit: CardCommit | null): DiffWorkspaceSource | null {
    if (!cardPath) return null
    if (!commit) return new WorktreeDiffWorkspaceSource(cardPath)
    if (commit.available === false) return null

    return new CommitDiffWorkspaceSource(commit, cardPath)
}

/** Fixed diff header plus a tabbed workspace that loads the changed-file list first and each file on demand. */
export function CardCommitDiffPanel(props: CardCommitDiffPanelProps) {
    const { binding, dataSource, onExit, selection } = props
    const commit = selection.kind === 'commit' ? selection.commit : null
    const isWorktree = selection.kind === 'worktree'
    const card = useActiveCard(binding, dataSource)
    const cardPath = card?.path ?? null
    const [workspace] = useState(() => new DiffWorkspaceService())
    const [search] = useState(() => new DiffWorkspaceSearchService())
    const source = useMemo(() => createWorkspaceSource(cardPath, commit), [cardPath, commit])
    const sourceKey = source?.key ?? null

    useEffect(() => {
        if (source) workspace.setSource(source)
    }, [source, workspace])

    useEffect(() => {
        search.reset()
    }, [search, sourceKey])

    useEffect(() => () => {
        workspace.reset()
        search.reset()
    }, [search, workspace])

    if (!cardPath) return null

    const handleKeyDown = (event: KeyboardEvent<HTMLDivElement>) => {
        search.handleKeyDown(event)
    }

    return (
        <Box
            aria-label={isWorktree ? 'Card worktree diff' : 'Card commit diff'}
            onKeyDown={handleKeyDown}
            role="region"
            sx={{ display: 'flex', flex: 1, flexDirection: 'column', minHeight: 0 }}
        >
            <Box sx={{ alignItems: 'center', borderBottom: '1px solid', borderColor: 'divider', display: 'flex', flexShrink: 0, gap: 1, p: 1.5 }}>
                <Box sx={{ flex: 1, minWidth: 0 }}>
                    <Typography variant="subtitle2">{isWorktree ? 'Current worktree changes' : cardCommitLabel(commit!.record)}</Typography>
                    <Typography color="text.secondary" variant="caption">
                        {isWorktree ? 'Current repository state' : `${new Date(commit!.committedAt).toLocaleString()} Â· ${commit!.commit.slice(0, 7)}`}
                    </Typography>
                </Box>
                <DiffWorkspaceSearchButton service={search} />
                <DiffViewModeControl />
                <Button onClick={onExit} size="small" variant="outlined">Exit diff</Button>
            </Box>
            {commit?.available === false ? (
                <Typography color="error" role="alert" sx={{ p: 2 }}>{UNAVAILABLE_COMMIT_MESSAGE}</Typography>
            ) : (
                <DiffWorkspace search={search} sourceKind={isWorktree ? 'worktree' : 'commit'} workspace={workspace} />
            )}
        </Box>
    )
}

import { Box } from '@mui/material'
import { useSyncExternalStore, type ReactNode } from 'react'
import { CardCommitDiffPanel } from './card_commit_diff_panel'
import { listCardCommitDiffDataSource } from './list_card_commit_diff_data_source'

interface ListCardCommitDiffPanelProps {
    children: ReactNode
}

/** Locally switches between the lifetime list-card editor and its selected commit diff. */
export function ListCardCommitDiffPanel(props: ListCardCommitDiffPanelProps) {
    const { children } = props
    const selection = useSyncExternalStore(
        listCardCommitDiffDataSource.subscribe,
        listCardCommitDiffDataSource.getSnapshot,
        listCardCommitDiffDataSource.getSnapshot,
    )

    return (
        <>
            {selection ? (
                <CardCommitDiffPanel
                    binding="list-card"
                    key={selection.commit.commit}
                    onExit={listCardCommitDiffDataSource.clear}
                    selection={{ commit: selection.commit, kind: 'commit' }}
                />
            ) : null}
            <Box
                hidden={!!selection}
                sx={{ display: selection ? 'none' : 'flex', flex: 1, flexDirection: 'column', minHeight: 0 }}
            >
                {children}
            </Box>
        </>
    )
}

import {
    getElectronApplicationStateBridge,
    type ElectronApplicationStateBridge,
} from './electron_application_state_bridge'

export const APPLICATION_STATE_MIGRATION_KEY = 'md2.localStorageMigrationComplete'
export const APPLICATION_STATE_MIGRATION_VALUE = '1'

export const MIGRATED_APPLICATION_STORAGE_KEYS = [
    'md2.actionPromptHeight',
    'md2.actionQuestionsBlockHeight',
    'md2.cardBodyPopover.size',
    'md2.cardRunPopupSize',
    'md2.colorScheme',
    'md2.customMarkdownStyle',
    'md2.github.accessToken',
    'md2.github.pendingCommitHeads',
    'md2.lastProject',
    'md2.markdownFileSearchMenuSize',
    'md2.markdownStyle',
    'md2.projectAgentPopupSize',
    'md2.reactConfig',
    'md2.recentLocalRepositories',
    'md2.remoteControl.endpoint',
    'md2.sentry.connections',
    'md2.splitWidth',
    'md2.themeMode',
    'search-panel-results-size',
] as const

function requireStoredValues(value: Record<string, string> | string | null): Record<string, string> {
    if (!value || typeof value !== 'object' || Array.isArray(value)) {
        throw new Error('Desktop application-state snapshot is invalid')
    }
    if (Object.values(value).some((storedValue) => typeof storedValue !== 'string')) {
        throw new Error('Desktop application-state snapshot values must be strings')
    }

    return { ...value }
}

function requireStoredValue(value: Record<string, string> | string | null): string | null {
    if (value === null || typeof value === 'string') return value

    throw new Error('Desktop application-state value is invalid')
}

function requireBrowserMode() {
    if (getElectronApplicationStateBridge()) {
        throw new Error('Desktop application state must be initialized before use')
    }
}

async function migrateLegacyValues(bridge: ElectronApplicationStateBridge, storedValues: Record<string, string>) {
    if (storedValues[APPLICATION_STATE_MIGRATION_KEY] === APPLICATION_STATE_MIGRATION_VALUE) return

    for (const key of MIGRATED_APPLICATION_STORAGE_KEYS) {
        if (storedValues[key] !== undefined) continue

        const legacyValue = window.localStorage.getItem(key)
        if (legacyValue === null) continue

        await bridge.write(key, legacyValue)
        storedValues[key] = legacyValue
    }

    await bridge.write(APPLICATION_STATE_MIGRATION_KEY, APPLICATION_STATE_MIGRATION_VALUE)
    storedValues[APPLICATION_STATE_MIGRATION_KEY] = APPLICATION_STATE_MIGRATION_VALUE
}

async function removeDesktopValue(bridge: ElectronApplicationStateBridge, key: string) {
    try {
        await bridge.remove(key)
    } catch (error) {
        console.error('Desktop application-state remove failed', error)
    }
}

async function writeDesktopValue(bridge: ElectronApplicationStateBridge, key: string, value: string) {
    try {
        await bridge.write(key, value)
    } catch (error) {
        console.error('Desktop application-state write failed', error)
    }
}

/** Provides synchronous reads from a loaded desktop snapshot or browser localStorage. */
export class ApplicationStorage implements Pick<Storage, 'getItem' | 'removeItem' | 'setItem'> {
    private bridge: ElectronApplicationStateBridge | null = null
    private desktopValues: Record<string, string> | null = null

    async initialize() {
        const bridge = getElectronApplicationStateBridge()
        if (!bridge) return

        const storedValues = requireStoredValues(await bridge.read(null))
        await migrateLegacyValues(bridge, storedValues)
        this.bridge = bridge
        this.desktopValues = storedValues
    }

    getItem(key: string) {
        if (this.desktopValues) return this.desktopValues[key] ?? null
        requireBrowserMode()

        return window.localStorage.getItem(key)
    }

    removeItem(key: string) {
        if (this.desktopValues && this.bridge) {
            delete this.desktopValues[key]
            void removeDesktopValue(this.bridge, key)

            return
        }
        requireBrowserMode()
        window.localStorage.removeItem(key)
    }

    setItem(key: string, value: string) {
        if (this.desktopValues && this.bridge) {
            this.desktopValues[key] = value
            void writeDesktopValue(this.bridge, key, value)

            return
        }
        requireBrowserMode()
        window.localStorage.setItem(key, value)
    }

    async readCurrentItem(key: string) {
        if (!this.desktopValues || !this.bridge) {
            requireBrowserMode()

            return window.localStorage.getItem(key)
        }

        const value = requireStoredValue(await this.bridge.read(key))
        if (value === null) delete this.desktopValues[key]
        else this.desktopValues[key] = value

        return value
    }

    async writeCurrentItem(key: string, value: string) {
        if (!this.desktopValues || !this.bridge) {
            requireBrowserMode()
            window.localStorage.setItem(key, value)

            return
        }

        await this.bridge.write(key, value)
        this.desktopValues[key] = value
    }

}

export const applicationStorage = new ApplicationStorage()
